    let mut s1 = S { p: P { init: true, has_dm: true, has_mt: true, has_gpu: false, writer: true, max_att: 1, bp_ms: 0, ..p_zero() },
                     g: snapshot!(W { used: 0, cap: 8192, ..w0() }) };
